<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f7fb;
      --card: #ffffff;
      --text: #172033;
      --muted: #667085;
      --primary: #3157d5;
      --primary-dark: #2442a6;
      --border: #d9e0ee;
      --ring: #8ea4ff;
      --shadow: 0 24px 70px rgba(23, 32, 51, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(49, 87, 213, 0.16), transparent 34rem),
        linear-gradient(180deg, #ffffff 0%, var(--bg) 45%);
    }

    main {
      width: min(100% - 2rem, 58rem);
      margin: 0 auto;
      padding: 4rem 0;
    }

    .quiz-shell {
      background: rgba(255, 255, 255, 0.88);
      border: 1px solid rgba(217, 224, 238, 0.84);
      border-radius: 1.5rem;
      box-shadow: var(--shadow);
      overflow: hidden;
      backdrop-filter: blur(14px);
    }

    .quiz-header {
      padding: 2.5rem;
      background: linear-gradient(135deg, #172033 0%, #3157d5 100%);
      color: #ffffff;
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: #c9d6ff;
    }

    h1 {
      max-width: 44rem;
      margin: 0;
      font-size: clamp(2rem, 5vw, 3.5rem);
      line-height: 1.05;
      letter-spacing: -0.05em;
    }

    .intro {
      max-width: 40rem;
      margin: 1rem 0 0;
      color: #e8edff;
      font-size: 1.05rem;
    }

    form {
      padding: 2rem;
    }

    .form-field {
      padding: 1.5rem;
      border: 1px solid var(--border);
      border-radius: 1rem;
      background: var(--card);
    }

    .form-field + .form-field {
      margin-top: 1rem;
    }

    fieldset {
      min-width: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin-bottom: 0.45rem;
      padding: 0;
      font-size: 1.2rem;
      font-weight: 750;
      letter-spacing: -0.02em;
    }

    .help-text {
      margin: 0 0 1rem;
      color: var(--muted);
    }

    .choice-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .choice {
      position: relative;
      display: flex;
      gap: 0.75rem;
      align-items: flex-start;
      min-height: 3.5rem;
      padding: 0.9rem 1rem;
      border: 1px solid var(--border);
      border-radius: 0.85rem;
      background: #fbfcff;
      cursor: pointer;
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: #aebced;
      box-shadow: 0 10px 28px rgba(23, 32, 51, 0.08);
      transform: translateY(-1px);
    }

    .choice input {
      width: 1.1rem;
      height: 1.1rem;
      margin: 0.15rem 0 0;
      accent-color: var(--primary);
      flex: 0 0 auto;
    }

    .choice:has(input:checked) {
      border-color: var(--primary);
      background: #eef3ff;
    }

    .choice:has(input:focus-visible) {
      outline: 3px solid var(--ring);
      outline-offset: 3px;
    }

    .choice span {
      font-weight: 650;
    }

    .actions {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      margin-top: 1.5rem;
    }

    button {
      min-height: 3rem;
      padding: 0 1.25rem;
      border: 0;
      border-radius: 999px;
      color: #ffffff;
      background: var(--primary);
      font: inherit;
      font-weight: 750;
      cursor: pointer;
      box-shadow: 0 14px 28px rgba(49, 87, 213, 0.22);
    }

    button:hover {
      background: var(--primary-dark);
    }

    button:focus-visible {
      outline: 3px solid var(--ring);
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--muted);
      font-weight: 650;
    }

    @media (max-width: 42rem) {
      main {
        padding: 1rem 0;
      }

      .quiz-header,
      form {
        padding: 1.25rem;
      }

      .choice-grid {
        grid-template-columns: 1fr;
      }

      .actions {
        align-items: stretch;
        flex-direction: column;
      }
    }
  </style>
</head>
<body>
  <main id="root" aria-labelledby="quiz-title"></main>

  <script>
    const questions = [
      {
        id: "language-types",
        prompt: "Which of these are programming languages?",
        helpText: "Select every answer that names a language used to write computer programs.",
        choices: ["Python", "HTML", "Java", "CSS"]
      },
      {
        id: "typed-languages",
        prompt: "Which languages are commonly described as statically typed?",
        choices: ["TypeScript", "Java", "Ruby", "C#"]
      },
      {
        id: "web-languages",
        prompt: "Which languages are often used for front-end web development?",
        choices: ["JavaScript", "TypeScript", "Swift", "CSS"]
      }
    ];

    function Choice({ questionId, choice }) {
      const id = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

      return `
        <label class="choice" for="${id}">
          <input id="${id}" name="${questionId}" type="checkbox" value="${choice}">
          <span>${choice}</span>
        </label>
      `;
    }

    function QuestionField({ id, prompt, helpText, choices }, index) {
      const helpId = helpText ? `${id}-help` : "";

      return `
        <div class="form-field">
          <fieldset ${helpId ? `aria-describedby="${helpId}"` : ""}>
            <legend>${index + 1}. ${prompt}</legend>
            ${helpText ? `<p class="help-text" id="${helpId}">${helpText}</p>` : ""}
            <div class="choice-grid">
              ${choices.map((choice) => Choice({ questionId: id, choice })).join("")}
            </div>
          </fieldset>
        </div>
      `;
    }

    function QuizApp() {
      return `
        <article class="quiz-shell">
          <header class="quiz-header">
            <p class="eyebrow">Computer languages</p>
            <h1 id="quiz-title">A quick multi-select quiz for curious developers.</h1>
            <p class="intro">Choose one or more answers for each question, then submit your selections.</p>
          </header>
          <form id="quiz-form">
            ${questions.map(QuestionField).join("")}
            <div class="actions">
              <button type="submit">Submit answers</button>
              <p class="status" id="quiz-status" role="status" aria-live="polite"></p>
            </div>
          </form>
        </article>
      `;
    }

    document.querySelector("#root").innerHTML = QuizApp();

    document.querySelector("#quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedCount = new FormData(event.currentTarget).getAll("language-types").length
        + new FormData(event.currentTarget).getAll("typed-languages").length
        + new FormData(event.currentTarget).getAll("web-languages").length;

      document.querySelector("#quiz-status").textContent =
        selectedCount === 1
          ? "Your 1 selected answer was submitted."
          : `Your ${selectedCount} selected answers were submitted.`;
    });
  </script>
</body>
</html>
